function makeSynapse({aPlus = 0.01, aMinus = 0.0105, tauPlus = 20, tauMinus = 20, wMax = 1} = {}) {
  let w = 0.5, x = 0, y = 0, last = 0;
  return {
    get w() { return w; },
    spike(t, isPre) {
      x *= Math.exp(-(t - last) / tauPlus);
      y *= Math.exp(-(t - last) / tauMinus);
      last = t;
      if (isPre) { w = Math.max(0, w - aMinus * wMax * y); x += 1; }
      else       { w = Math.min(wMax, w + aPlus * wMax * x); y += 1; }
    },
  };
}
